module testbench3(); 
    // reset for sequential logic
    logic clk, reset; 

    // input wires, from txt file
    logic a, b, c, yexpected; 
    
    // output generated by the logic simulation 
    logic y; 

    logic [31:0] vectornum, errors; // bookkeeping variables

    // 4 cols width (inputs and outputs), 10k rows filled with diff. tests
    logic [3:0] testvectors[10000:0]; // array of testvectors

    // initiate the dut 
    sillyfunction dut(a, b, c, y); 

    // generate clock
    always // no sens list, always execute
        begin 
            clk = 1; #5; clk = 0; #5; 
        end

    // at start of test, load vectors and pulse reset
    initial begin
        // binary format, we only need 0-7, so rest is not used
        // if written in hex: $readmemh
        $readmemb("29_testvector.txt", testvectors); 
        vectornum = 0; errors = 0; // counters
        reset = 1; #22; reset = 0; // comb here, but for sync seq needed
    end 

    // apply test vectors on rising edge of clk 
    always @(posedge clk) begin 
        #1; {a, b, c, yexpected} = testvectors[vectornum]; 
    end

    // check results on falling edge of clk 
    always @(negedge clk) 
        if(~reset) begin // skip during reset 
            if (y !== yexpected) begin 
                $display("Error: inputs = %b", {a, b, c}); // for hex: %h
                $display(" outputs = %b (%b expected)", y, yexpected); 
                errors = errors + 1; 
            end 

            // increment array index and read next testvector
            vectornum = vectornum + 1; 

            // === and !== can compare 1, 0, x (undefined) or z (floating)
            if(testvectors[vectornum] === 4'bx) begin 
                $display("%d tests completed with %d errors", vectornum, errors); 
                $stop; 
            end
        end
endmodule

        